import re, sys, json, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from dec1 import act, ins
import dec2, dec3, dec4, dec5

SRC = sys.argv[1]
OUT_PLAN = sys.argv[2]
OUT_HIST = sys.argv[3]
lines = open(SRC, encoding='utf-8').read().split('\n')
if lines and lines[-1] == '':
    lines = lines[:-1]
N = len(lines)
L = lambda i: lines[i - 1]

missing = [i for i in range(1, N + 1) if L(i).strip() and i not in act]
extra = [i for i in act if i > N or not L(i).strip()]
if missing:
    sys.exit('no decision for lines %s' % missing)

def indent(s):
    return len(s) - len(s.lstrip(' '))

def is_item(s):
    t = s.lstrip(' ')
    return t.startswith('- ') or bool(re.match(r'\d+\. ', t))

def expand(text):
    return re.sub(r'\{L(\d+)\}', lambda m: L(int(m.group(1))), text)

# ---- PLAN
out = []          # list of [text, blank_after]
def emit(text, blank_after):
    out.append([text, blank_after])
def emit_block(text):
    if out:
        out[-1][1] = True
    emit(expand(text), True)

for i in range(1, N + 1):
    s = L(i)
    if s.strip():
        a = act[i]
        nxt_blank = (i == N) or not L(i + 1).strip()
        if a == 'keep':
            emit(s, nxt_blank)
        elif isinstance(a, tuple) and a[0] == 'repl':
            emit(a[1], nxt_blank)
        elif a in ('out', 'drop'):
            if nxt_blank and out:
                pass
        else:
            sys.exit('bad act %r at %d' % (a, i))
    for block in ins.get(i, []):
        emit_block(block)

# a paragraph ends where the original paragraph ended, even when its last line moved out
# (fix: if a kept line is followed by moved lines that end a paragraph, it ends one too)
res = []
for i in range(1, N + 1):
    pass
text = ''
for t, b in out:
    text += t + '\n' + ('\n' if b else '')
# paragraph breaks lost by moved lines: a list item followed directly by a heading or a label gets a blank
fixed = []
prev = ''
for ln in text.split('\n'):
    if ln.strip() and prev.strip():
        if ln.startswith('#') or (not is_item(ln) and not ln.startswith(' ') and is_item(prev)) \
           or (is_item(ln) and not is_item(prev) and not prev.startswith('#') and prev.rstrip().endswith(':') is False):
